cat > index.js <<'EOF'
import toRegexRange from 'to-regex-range';

const RANGE_PATTERN = /^\s*(-?\d+)\s*-\s*(-?\d+)\s*$/;

/**
 * Parse a range string like "1-100" (or "-10--5") into [min, max].
 */
export function parseRange(input) {
  const match = RANGE_PATTERN.exec(input);
  if (!match) {
    throw new Error(`Invalid range "${input}". Expected format: <min>-<max>, e.g. 1-100`);
  }
  const min = Number(match[1]);
  const max = Number(match[2]);
  if (!Number.isSafeInteger(min) || !Number.isSafeInteger(max)) {
    throw new Error(`Range bounds must be safe integers: "${input}"`);
  }
  return min <= max ? [min, max] : [max, min];
}

/**
 * Build a RegExp that matches exactly the integers in the given range.
 * Anchored by default so "150" doesn't match inside 1-100 via "15".
 */
export function rangeToRegex(input, { anchored = true } = {}) {
  const [min, max] = parseRange(input);
  const source = toRegexRange(min, max, { capture: false, shorthand: true });
  return new RegExp(anchored ? `^(?:${source})$` : source);
}
EOF
cat > cli.js <<'EOF'
#!/usr/bin/env node
import { rangeToRegex } from './index.js';

const args = process.argv.slice(2);
const anchored = !args.includes('--no-anchor');
const range = args.find((a) => !a.startsWith('--'));

if (!range) {
  console.error('Usage: range-to-regex <min>-<max> [--no-anchor]');
  process.exit(1);
}

try {
  console.log(rangeToRegex(range, { anchored }).source);
} catch (err) {
  console.error(err.message);
  process.exit(1);
}
EOF
chmod +x cli.js
mkdir -p test && cat > test/index.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { parseRange, rangeToRegex } from '../index.js';

function assertExact(range, lo, hi, margin = 50) {
  const re = rangeToRegex(range);
  for (let n = lo - margin; n <= hi + margin; n++) {
    assert.equal(re.test(String(n)), n >= lo && n <= hi, `${range} vs ${n}`);
  }
}

test('matches exactly 1-100', () => assertExact('1-100', 1, 100));
test('handles arbitrary bounds', () => assertExact('37-1234', 37, 1234));
test('handles single value', () => assertExact('42-42', 42, 42));
test('handles negative ranges', () => assertExact('-25--3', -25, -3));
test('handles ranges spanning zero', () => assertExact('-10-10', -10, 10));
test('normalizes reversed bounds', () => assert.deepEqual(parseRange('100-1'), [1, 100]));

test('rejects malformed input', () => {
  for (const bad of ['', 'abc', '1-', '1..100', '1-2-3']) {
    assert.throws(() => parseRange(bad), /Invalid range/);
  }
});

test('anchoring prevents partial matches', () => {
  assert.equal(rangeToRegex('1-100').test('150'), false);
  assert.equal(rangeToRegex('1-100', { anchored: false }).test('150'), true);
});
EOF
cat > .gitignore <<'EOF'
node_modules/
EOF
npm test 2>&1 | tail -9; ./cli.js 1-100; ./cli.js 37-1234; ./cli.js foo

